class Solution:
    def numSubmat(self, mat: list[list[int]]) -> int:
        m, n = len(mat), len(mat[0])
        height = [0] * n
        total = 0
        for i in range(m):
            for j in range(n):
                height[j] = height[j] + 1 if mat[i][j] == 1 else 0
            # For this row, count submatrices
            for j in range(n):
                min_h = height[j]
                for k in range(j, -1, -1):
                    if height[k] == 0:
                        break
                    min_h = min(min_h, height[k])
                    total += min_h
        return total

